// === Tab: mySketch ===
//For the #wccChallenge on theme of 'Don't touch'.
//The hands are mine, photographed by me.
//The stop-motion frames are moving through an array via simplex noise (perlin's effect was not smooth enough)
//and setting off the other effects above frame 17.

//I retitled it several times before leaving it untitled. I think because any title seemed
//to give it too specific a meaning.




let h1, h2, h3, h4, h5, h6, h7, h8, h9, h10, h11, h12, h13, h14, h15, h16, h17, h18, h19, h20, h21
let hand=[]
let simplex
let streamers=[]

function preload(){
h1=loadImage('https://openprocessing.org/sketch/2292631/files/7585.jpeg');
