h10=loadImage('https://openprocessing.org/sketch/2292631/files/7594.jpeg');
h11=loadImage('https://openprocessing.org/sketch/2292631/files/7595.jpeg');
h12=loadImage('https://openprocessing.org/sketch/2292631/files/7596.jpeg');
h13=loadImage('https://openprocessing.org/sketch/2292631/files/7597.jpeg');
h14=loadImage('https://openprocessing.org/sketch/2292631/files/7598.jpeg');
h15=loadImage('https://openprocessing.org/sketch/2292631/files/7599.jpeg');
h16=loadImage('https://openprocessing.org/sketch/2292631/files/7600.jpeg');
h17=loadImage('https://openprocessing.org/sketch/2292631/files/7601.jpeg');
h18=loadImage('https://openprocessing.org/sketch/2292631/files/7602.jpeg');
h19=loadImage('https://openprocessing.org/sketch/2292631/files/7603.jpeg');
h20=loadImage('https://openprocessing.org/sketch/2292631/files/7604.jpeg');
h21=loadImage('https://openprocessing.org/sketch/2292631/files/7605.jpeg');


}

function setup() {
	createCanvas(1100, 650);


	simplex= new OpenSimplexNoise(Date.now())
	background(255);
	hand.push(h1, h1, h2,h2,  h3, h4, h5, h6, h7, h8, h9, h10, h11, h12, h13, h14, h15, h16, h17, h18, h19, h20, h21, h21, h21, h21);	

}

function draw() {
	background(255);

	let hframe= floor(map(simplex.noise2D(frameCount/70, 21), -1, 1, 0, hand.length))

	let pic= hand[hframe]
	push()
	translate(0, 100)
	scale(0.5, 0.5)
	image(pic, 0, 0)
pop()
	push()
	translate(width, 100)
	scale(-0.5,0.5) 
	image(pic, 0, 0)
	pop()
	stroke(20)
	if(hframe>17){
		for(let i=0; i<3; i++){
			for (let i = 0; i < 800; i++) {
		strokeWeight(random(3))
		push()
		translate(randomGaussian(width / 2, 50), randomGaussian(150, 50))
		line(-5, 0, +5, 0)
		line(0, -5, 0, 5)
		pop()
	}
	streamers.push(new streamer())	
		}
	}


	for(let i=0; i<streamers.length; i++){

	streamers[i].stream();
	streamers[i].show();
	streamers[i].shutup();
	}
}


class streamer{
	constructor(){
		this.length=1
		this.rot= random(TWO_PI)
		this.dist=50
		this.theta=random(10000)
		this.targetLength=random(30, 150)
	}

	shutup(){
		if(this.dist-this.length>250){
			let index = streamers.indexOf(this);
      streamers.splice(index, 1);
		}
	}

	stream(){
		if(this.length<this.targetLength){
			this.length+=1
		}
		this.dist+=2
		this.theta+=0.2
	}
	show(){
		let alpha
		let alphaWobble= noise(this.theta)
		strokeCap(SQUARE)
		if(alphaWobble>0.3){
		alpha=255
		} else{
		alpha=0
		}
		let sw= map(sin(this.theta), -1, 1, 0.1, 3)
		strokeWeight(sw)
		stroke(255, alpha)
		push()
		translate(width/2, 150)
		rotate(this.rot);
		line(this.dist, 0, this.dist - this.length, 0)
		pop()
	}
}

